using Erp.Abstractions.Context;
using Erp.Modules.Purchasing;
using Erp.SharedKernel;
using Microsoft.EntityFrameworkCore;
namespace Erp.IntegrationTests; public sealed class PurchasingPostgresTests { [Fact] public async Task OrdersAreCompanyIsolatedAndConcurrent() { var pg = await IntegrationContainers.StartPostgresAsync("purchasing_tests"); await using (pg) { var tenant = Guid.NewGuid(); var a = Guid.NewGuid(); var b = Guid.NewGuid(); var id = Guid.NewGuid(); var options = new DbContextOptionsBuilder<PurchasingDbContext>().UseNpgsql(pg.GetConnectionString()).Options; await using (var m = new PurchasingDbContext(options)) await m.Database.MigrateAsync(); await using (var w = new PurchasingDbContext(options, new T(tenant), new C(a))) { var now = DateTimeOffset.UtcNow; var order = new PurchaseOrder { Id = id, TenantId = tenant, CompanyId = a, Number = "PO-TEST-1", SupplierId = Guid.NewGuid(), SupplierName = "Supplier", CurrencyCode = "USD", BaseCurrencyCode = "USD", ExchangeRate = 1, OrderDate = DateOnly.FromDateTime(now.UtcDateTime), State = PurchaseOrderState.Draft, Subtotal = 10, Total = 10, CreatedAtUtc = now, UpdatedAtUtc = now, ConcurrencyStamp = Guid.NewGuid().ToString("N") }; order.Lines.Add(new() { Id = Guid.NewGuid(), TenantId = tenant, CompanyId = a, PurchaseOrderId = id, Sequence = 1, ProductId = Guid.NewGuid(), ProductSku = "SKU", Description = "Snapshot", UnitCode = "EA", Quantity = 1, UnitPrice = 10, Subtotal = 10, Total = 10 }); w.PurchaseOrders.Add(order); await w.SaveChangesAsync(); } await using var visible = new PurchasingDbContext(options, new T(tenant), new C(a)); await using var hidden = new PurchasingDbContext(options, new T(tenant), new C(b)); Assert.Single((await visible.PurchaseOrders.Include(x => x.Lines).SingleAsync()).Lines); Assert.Empty(await hidden.PurchaseOrders.ToListAsync()); Assert.Empty(await hidden.PurchaseOrderLines.ToListAsync()); var first = await visible.PurchaseOrders.SingleAsync(); await using (var other = new PurchasingDbContext(options, new T(tenant), new C(a))) { var second = await other.PurchaseOrders.SingleAsync(); second.Notes = "changed"; second.ConcurrencyStamp = Guid.NewGuid().ToString("N"); await other.SaveChangesAsync(); } first.Notes = "stale"; first.ConcurrencyStamp = Guid.NewGuid().ToString("N"); await Assert.ThrowsAsync<DbUpdateConcurrencyException>(() => visible.SaveChangesAsync()); } } private sealed class T(Guid id) : ITenantContext { public TenantId? TenantId { get; } = new(id); } private sealed class C(Guid id) : ICompanyContext { public CompanyId? CompanyId { get; } = new(id); } }
